def esc(s): return html.escape(str(s or ''), quote=True)

def field(md,label):
    m=re.search(r'^- \*\*'+re.escape(label)+r':\*\* (.+)$',md,re.M)
    return m.group(1).strip().strip('`') if m else ''
def block(md,a,b):
    m=re.search(re.escape(a)+r'\s*\n\n(.+?)\n\n'+re.escape(b),md,re.S)
    return m.group(1).strip() if m else ''

def load():
    rows=[]
    for p in sorted(ROOT.glob('*.md')):
        md=p.read_text(encoding='utf-8')
        cm=re.search(r'unique_code: "([^"]+)"',md); nm=re.search(r'^# (.+)$',md,re.M)
        if not(cm and nm): continue
        code=cm.group(1)
        src=block(md,'## Sources','## Research scope')
        sources=re.findall(r'- \[([^\]]+)\]\((https?://[^)]+)\) — ([^\n]+)',src)
        website=''
        wm=re.search(r'- \*\*Website:\*\* (https?://\S+)',md)
        if wm: website=wm.group(1).strip()
        status=field(md,'Operational status') or re.search(r'^status: "([^"]+)"',md,re.M).group(1)
        r=dict(code=code,name=field(md,'Current Google Maps name') or nm.group(1),title=nm.group(1),category=field(md,'Current Maps category') or field(md,'Category in CSV'),csvcat=field(md,'Category in CSV'),area=field(md,'Area'),status=status,rating=field(md,'Rating'),reviews=field(md,'Review count'),address=field(md,'Address'),phone=field(md,'Phone'),hours=field(md,'Hours'),maps=field(md,'Exact Google Maps URL'),website=website,summary=block(md,'## Executive summary','## Identity'),finding=block(md,'## Research findings','## Data-quality and discrepancy notes'),sources=sources,photo=PHOTO_MAP.get(code),status_note=STATUS_NOTES.get(code,''))
        if r['finding'].strip()==r['summary'].strip(): r['finding']='The exact Google Maps Place ID is the identity anchor for this page. Contact details, hours, ratings and operating status are point-in-time and should be checked again before visiting.'
        layout,a,b=DNA.get(code,('minimal','#866','#aaa'))
        r['layout']=layout; r['dna_a']=a;r['dna_b']=b
        rows.append(r)
    return rows

def catkey(r):
    c=(r['category']+' '+r['csvcat']).lower(); st=r['status'].lower()
    if 'closed' in st: return 'closed'
    if any(x in c for x in ['beauty','salon','spa','massage']): return 'beauty'
    if 'barber' in c or 'gents salon' in c: return 'barber'
    if any(x in c for x in ['laundry','cleaner']): return 'laundry'
    if any(x in c for x in ['restaurant','cafeteria','falafel','gelato','japanese']): return 'food'
    if any(x in c for x in ['grocery','supermarket','minimart','convenience']): return 'grocery'
    if any(x in c for x in ['tailor','clothing','embroidery','boutique']): return 'tailor'
    if any(x in c for x in ['garage','car repair','auto']): return 'auto'
    if any(x in c for x in ['electronics','mobile phone']): return 'electronics'
    return 'industrial'

def seed(code): return int(hashlib.sha256(code.encode()).hexdigest()[:8],16)

